Here's a high-level pseudocode to help you get started:

```
#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>

// Define game constants
#define BOARD_WIDTH 20
#define BOARD_HEIGHT 15
#define SNAKE_SEGMENT_SIZE 20
#define FOOD_RADIUS 10

// Define game entities
typedef struct {
    int x, y;
    SDL_Surface *image;
} SnakeSegment;

typedef struct {
    int x, y;
    SDL_Surface *image;
} Food;

typedef struct {
    SnakeSegment *head;
    int length;
    SDL_Surface *segment_image;
    SDL_Surface *head_image;
} Snake;

typedef struct {
    SDL_Window *window;
    SDL_Renderer *renderer;
    SDL_Surface *background_image;
    SDL_Surface *food_image;
    SDL_Surface *score_font;

    Snake snake;
    Food food;
    int score;
    int fps;
    Uint32 last_frame_time;
} GameContext;

// Initialize SDL2 and create the game context
GameContext *init_game(void);

// Free resources allocated by the game context
void free_game(GameContext *ctx);

// Update the game state
void update_game(GameContext *ctx);

// Render the game state
void render_game(GameContext *ctx);

// Handle user input
void handle_input(GameContext *ctx);

// Load assets
SDL_Surface *load_image(const char *path);
void load_assets(GameContext *ctx);

// Main game loop
int run_game(void);

int main(void) {
    int result = run_game();
    free_game((GameContext *) NULL);
    return result;
}

GameContext *init_game(void) {
    GameContext *ctx = malloc(sizeof(*ctx));

    if (SDL_Init(SDL_INIT_VIDEO | SDL_INIT_AUDIO) < 0) {
        SDL_LogError(SDL_LOG_CATEGORY_APPLICATION, "SDL initialization failed: %s\n", SDL_GetError());
        free(ctx);
        return NULL;
    }

    if (TTF_Init() < 0) {
        SDL_LogError(SDL_LOG_CATEGORY_APPLICATION, "TTF initialization failed: %s\n", TTF_GetError());
        SDL_Quit();
        free(ctx);
        return NULL;
    }

    if (!(ctx->window = SDL_CreateWindow("Snake",
                                         SDL_WINDOWPOS_CENTERED_DISPLAY(0),
                                         SDL_WINDOWPOS_CENTERED_DISPLAY(0),
                                         BOARD_WIDTH * SNAKE_SEGMENT_SIZE,
                                         BOARD_HEIGHT * SNAKE_SEGMENT_SIZE,
                                         SDL_WINDOW_SHOWN))) {
        SDL_LogError(SDL_LOG_CATEGORY_APPLICATION, "Window creation failed: %s\n", SDL_GetError());
        TTF_Quit();
        SDL_Quit();
        free(ctx);
        return NULL;
    }

    if (!(ctx->renderer = SDL_CreateRenderer(ctx->window, -1, SDL_RENDERER_ACCELERATED))) {
        SDL_LogError(SDL_LOG_CATEGORY_APPLICATION, "Renderer creation failed: %s\n", SDL_GetError());
        SDL_DestroyWindow(ctx->window);
        TTF_Quit();
        SDL_Quit();
        free(ctx);
        return NULL;
    }

    ctx->background_image = load_image("background.png");
    ctx->food_image = load_image("food.png");
    ctx->score_font = TTF_RenderText_Solid(ctx->font, "Score: 0", SDL_Color { 255, 255, 255 });

    Snake *snake = malloc(sizeof(*snake));
    snake->head = malloc(sizeof(*snake->head));
    snake->head->x = BOARD_WIDTH / 2;
    snake->head->y = BOARD_HEIGHT / 2;
    snake->length = 1;
    snake->segment_image = load_image("segment.png");
    snake->head_image = load_image("head.png");

    Food *food = malloc(sizeof(*food));
    food->x = rand() % (BOARD_WIDTH - 2 * FOOD_RADIUS) + FOOD_RADIUS;
    food->y = rand() % (BOARD_HEIGHT - 2 * FOOD_RADIUS) + FOOD_RADIUS;

    ctx->snake = *snake;
    ctx->food = *food;

    ctx->fps = 60;
    ctx->last_frame_time = SDL_GetPerformanceCounter();

    return ctx;
}

void free_game(GameContext *ctx) {
    SDL_DestroyRenderer(ctx->renderer);
    SDL_DestroyWindow(ctx->window);
    TTF_CloseFont(ctx->font);

    SDL_FreeSurface(ctx->background_image);
    SDL_FreeSurface(ctx->food_image);
    SDL_FreeSurface(ctx->score_font);

    free(ctx->snake.head);
    free(ctx->snake.head);
    free(ctx);

    SDL_Quit();
    TTF_Quit();
}

void update_game(GameContext *ctx) {
    // Handle input
    handle_input(ctx);

    // Move snake
    SnakeSegment *tail = ctx->snake.head;
    while (tail->next) {
        tail->x = tail->next->x;
        tail->y = tail->next->y;
        tail = tail->next;
    }

    // Check if snake ate food
    int dx = ctx->food.x - ctx->snake.head->x;
    int dy = ctx->food.y - ctx->snake.head->y;
    if (dx == 0 && dy == 0) {
        ctx->score++;
        SnakeSegment *new_tail = malloc(sizeof(*new_tail));
        new_tail->x = tail->x;
        new_tail->y = tail->y;
        tail->next = new_tail;
        ctx->snake.length++;
        ctx->food.x = rand() % (BOARD_WIDTH - 2 * FOOD_RADIUS) + FOOD_RADIUS;
        ctx->food.y = rand() % (BOARD_HEIGHT - 2 * FOOD_RADIUS) + FOOD_RADIUS;
    }

    // Move snake head
    if (ctx->snake.head->x < 0 || ctx->snake.head->x >= BOARD_WIDTH ||
        ctx->snake.head->y < 0 || ctx->snake.head->y >= BOARD_HEIGHT) {
        // Snake hit the border
    } else {
        SnakeSegment *new_head = malloc(sizeof(*new_head));
        new_head->x = ctx->snake.head->x + dx / SNAKE_SEGMENT_SIZE;
        new_head->y = ctx->snake.head->y + dy / SNAKE_SEGMENT_SIZE;
        new_head->next = ctx->snake.head;
        ctx->snake.head = new_head;
    }
}

void render_game(GameContext *ctx) {
    SDL_SetRenderDrawColor(ctx->renderer, 0, 0, 0, SDL_ALPHA_OPAQUE);
    SDL_RenderClear(ctx->renderer);

    // Render board background
    SDL_Rect dstrect = { 0, 0, BOARD_WIDTH * SNAKE_SEGMENT_SIZE, BOARD_HEIGHT * SNAKE_SEGMENT_SIZE };
    SDL_RenderCopy(ctx->renderer, ctx->background_image, NULL, &dstrect);

    // Render snake
    SnakeSegment *seg = ctx->snake.head;
    while (seg) {
        SDL_Rect srcrect = {
            seg->x * SNAKE_SEGMENT_SIZE, seg->y * SNAKE_SEGMENT_SIZE,
            SNAKE_SEGMENT_SIZE, SNAKE_SEGMENT_SIZE
        };
        SDL_Rect dstrect = {
            seg->x * SNAKE_SEGMENT_SIZE, seg->y * SNAKE_SEGMENT_SIZE,
            SNAKE_SEGMENT_SIZE, SNAKE_SEGMENT_SIZE
        };
        if (seg == ctx->snake.head) {
            SDL_RenderCopy(ctx->renderer, ctx->snake.head_image, NULL, &dstrect);
        } else {
            SDL_RenderCopy(ctx->renderer, ctx->snake.segment_image, NULL, &dstrect);
        }
        seg = seg->next;
    }

    // Render food
    SDL_Rect srcrect = {
        ctx->food.x - FOOD_RADIUS, ctx->food.y - FOOD_RADIUS,
        2 * FOOD_RADIUS, 2 * FOOD_RADIUS
    };
    SDL_Rect dstrect = {
        ctx->food.x * SNAKE_SEGMENT_SIZE - FOOD_RADIUS, ctx->food.y * SNAKE_SEGMENT_SIZE - FOOD_RADIUS,
        2 * FOOD_RADIUS * SNAKE_SEGMENT_SIZE, 2 * FOOD_RADIUS * SNAKE_SEGMENT_SIZE
    };
    SDL_RenderCopy(ctx->renderer, ctx->food_image, &srcrect, &dstrect);

    // Render score
    char score_text[16];
    sprintf(score_text, "Score: %d", ctx->score);
    SDL_Surface *score_surface = TTF_RenderText_Solid(ctx->score_font, score_text, SDL_Color { 255, 255, 255 });
    SDL_Rect score_rect = {
        BOARD_WIDTH * SNAKE_SEGMENT_SIZE - 150, 0,
        score_surface->w, score_surface->h
    };
    SDL_RenderCopy(ctx->renderer, score_surface, NULL, &score_rect);
    SDL_FreeSurface(score_surface);

    SDL_RenderPresent(ctx->renderer);
}

void handle_input(GameContext *ctx) {
    SDL_Event event;
    while (SDL_PollEvent(&event)) {
        switch (event.type) {
            case SDL_KEYDOWN:
                switch (event.key.keysym.sym) {
                    case SDLK_LEFT:
                        if (ctx->snake.head->x > 0)
                            ctx->snake.head->x--;
                        break;
                    case SDLK_RIGHT:
                        if (ctx->snake.head->x < BOARD_WIDTH - 1)
                            ctx->snake.head->x++;
                        break;
                    case SDLK_UP:
                        if (ctx->snake.head->y > 0)
                            ctx->snake.head->y--;
                        break;
                    case SDLK_DOWN:
                        if (ctx->snake.head->y < BOARD_HEIGHT - 1)
                            ctx->snake.head->y++;
                        break;
                }
                break;
            case SDL_QUIT:
                SDL_DestroyWindow(ctx->window);
                TTF_Quit();
                SDL_Quit();
                exit(0);
                break;
        }
    }
}

SDL_Surface *load_image(const char *path) {
    SDL_Surface *surface = IMG_Load(path);
    if (!surface) {
        SDL_LogError(SDL_LOG_CATEGORY_APPLICATION, "Failed to load image %s: %s\n", path, IMG_GetError());
        exit(EXIT_FAILURE);
    }
    return surface;
}

int run_game(void) {
    GameContext *ctx = init_game();

    if (!ctx) {
        return 1;
    }

    Uint32 start_time, end_time, wait_time;
    while (true) {
        start_time = SDL_GetPerformanceCounter();

        update_game(ctx);
        render_game(ctx);

        end_time = SDL_GetPerformanceCounter();
        wait_time = ctx->fps * 1000 / (end_time - ctx->last_frame_time) - (SDL_GetTicks() - ctx->last_frame_time);
        if (wait_time > 0) {
            SDL_Delay(wait_time);
        }

        ctx->last_frame_time = end_time;
    }

    free_game(ctx);
    return 0;
}
```

